            const added = await module.journalWorkspaceTrackAdd(
              current,
              {
                id: trackId,
                kind: "INSTRUMENT",
                name: catalog?.label ?? item.instrument,
              },
              nextAudioWorkspaceMutation("midi-import-track"),
            );
