            const cameraDetailsSummary = documentRef.createElement("summary");
            cameraDetailsSummary.textContent = "2Dカメラの動き";
            const cameraFields = documentRef.createElement("div");
            cameraFields.className = "draw2-game-camera-fields";
            const addCameraSection = (text: string): void => {
              const heading = documentRef.createElement("span");
              heading.className = "draw2-game-camera-section-heading";
              heading.textContent = text;
              cameraFields.append(heading);
            };
            const referenceWidth = numberControl(
              settings.referenceWidth,
              "1",
            );
            referenceWidth.min = "1";
            referenceWidth.max = "8192";
            const referenceHeight = numberControl(
              settings.referenceHeight,
              "1",
            );
            referenceHeight.min = "1";
            referenceHeight.max = "8192";
            const pixelsPerUnit = numberControl(
              settings.pixelsPerUnit,
              "1",
            );
            pixelsPerUnit.min = "1";
            pixelsPerUnit.max = "1024";
            const pixelPerfect = checkboxControl(settings.pixelPerfect);
            appendComponentField(cameraFields, "Pixel-perfect", pixelPerfect);
            appendComponentField(cameraFields, "基準幅", referenceWidth);
            appendComponentField(cameraFields, "基準高さ", referenceHeight);
            appendComponentField(cameraFields, "Pixels Per Unit", pixelsPerUnit);
            addCameraSection("追従");
            const followEnabled = checkboxControl(settings.follow.enabled);
            const followTarget = documentRef.createElement("select");
            const noFollowTarget = documentRef.createElement("option");
            noFollowTarget.value = "";
            noFollowTarget.textContent = "追従なし";
            followTarget.append(noFollowTarget);
            const followTracks = gameDeckTracks.filter((track) =>
              track.id !== selected.id &&
              (track.role ?? gameObjectRoleFor(track.id, track.kind)) !==
                "CAMERA" &&
              track.kind !== "EVENT"
            );
            for (const track of followTracks) {
              const option = documentRef.createElement("option");
              option.value = track.id;
              option.textContent = track.label;
              followTarget.append(option);
            }
            followTarget.value = settings.follow.targetId ?? "";
            const smoothing = numberControl(settings.follow.smoothing, "0.01");
            smoothing.min = "0";
            smoothing.max = "2";
            const deadZoneX = numberControl(settings.follow.deadZoneX, "0.25");
            deadZoneX.min = "0";
            deadZoneX.max = "64";
            const deadZoneY = numberControl(settings.follow.deadZoneY, "0.25");
            deadZoneY.min = "0";
            deadZoneY.max = "64";
            const lookAheadX = numberControl(
              settings.follow.lookAheadX,
              "0.25",
            );
            lookAheadX.min = "-64";
            lookAheadX.max = "64";
            const lookAheadY = numberControl(
              settings.follow.lookAheadY,
              "0.25",
            );
            lookAheadY.min = "-64";
            lookAheadY.max = "64";
            appendComponentField(cameraFields, "追従を有効化", followEnabled);
            appendComponentField(cameraFields, "追従ターゲット", followTarget);
            appendComponentField(cameraFields, "追従の滑らかさ (秒)", smoothing);
            appendComponentField(cameraFields, "デッドゾーン X", deadZoneX);
            appendComponentField(cameraFields, "デッドゾーン Y", deadZoneY);
            appendComponentField(cameraFields, "先読み X", lookAheadX);
            appendComponentField(cameraFields, "先読み Y", lookAheadY);
            addCameraSection("ダメージ時の揺れ");
            const shakeOnDamage = checkboxControl(settings.shake.onDamage);
            const shakeStrength = numberControl(settings.shake.strength, "0.05");
            shakeStrength.min = "0";
            shakeStrength.max = "64";
            const shakeDuration = numberControl(
              settings.shake.durationMs,
              "10",
            );
            shakeDuration.min = "0";
            shakeDuration.max = "10000";
            const shakeFrequency = numberControl(
              settings.shake.frequency,
              "1",
            );
            shakeFrequency.min = "1";
            shakeFrequency.max = "120";
            appendComponentField(cameraFields, "ダメージで揺らす", shakeOnDamage);
            appendComponentField(cameraFields, "強さ", shakeStrength);
            appendComponentField(cameraFields, "時間 (ms)", shakeDuration);
            appendComponentField(cameraFields, "周波数", shakeFrequency);
            const cameraActionRow = documentRef.createElement("div");
            cameraActionRow.className = "draw2-game-camera-action-row";
            const testShake = documentRef.createElement("button");
            testShake.type = "button";
